import assert from 'node:assert/strict';
import {easterSunday,holidayForDate,adventCandles,dateParts,observedHoliday} from './holiday-engine.mjs';
const t=(s)=>new Date(s+'T12:00:00Z');
const H=(s,config)=>holidayForDate(t(s),'Europe/Bratislava',config||{});
for(const [year,date] of [[2025,'2025-04-20'],[2026,'2026-04-05'],[2027,'2027-03-28'],[2028,'2028-04-16'],[2029,'2029-04-01'],[2030,'2030-04-21']]){
  assert.equal(easterSunday(year).toISOString().slice(0,10),date,`Easter ${year}`);
}
assert.equal(H('2026-11-28').type,'none');
assert.equal(H('2026-11-29').type,'advent');
assert.equal(H('2026-11-29').candles,1);
assert.equal(H('2026-12-06').candles,2);
assert.equal(H('2026-12-13').candles,3);
assert.equal(H('2026-12-20').candles,4);
assert.equal(H('2026-12-15').type,'advent');
assert.equal(H('2026-12-15').candles,3);
assert.equal(H('2026-12-16').type,'advent');
assert.equal(H('2026-12-16').candles,3);
assert.equal(H('2026-12-20').candles,4);
assert.equal(H('2026-12-24').type,'christmas');
assert.equal(H('2026-12-24').label,'Štedrý deň');
assert.equal(H('2026-12-25').label,'Prvý sviatok vianočný');
assert.equal(H('2026-12-26').label,'Druhý sviatok vianočný');
assert.equal(H('2026-12-31').type,'newyear');
assert.equal(H('2027-01-01').type,'newyear');
assert.equal(H('2027-01-05').type,'christmas');
assert.equal(H('2027-01-06').label,'Traja králi');
assert.equal(H('2027-01-07').type,'none');
assert.equal(H('2026-04-05').type,'easter');
assert.equal(H('2026-04-06').label,'Veľkonočný pondelok');
assert.equal(H('2026-03-29').label,'Kvetná nedeľa');
assert.equal(H('2026-05-01').type,'spring');
assert.equal(H('2026-05-10').id,'mother');
assert.equal(H('2026-06-01').id,'child');
assert.equal(H('2026-11-01').type,'remembrance');
assert.equal(H('2026-11-17').label,'Deň boja za slobodu a demokraciu');
assert.equal(H('2026-12-06').id,'nicholas');
assert.equal(H('2027-11-28').candles,1);
assert.equal(H('2026-12-24',{holidays_enabled:false}).type,'none');
assert.equal(H('2026-06-15',{preview_holiday:'christmas'}).type,'christmas');
assert.equal(H('2026-06-15',{preview_date:'2026-12-24'}).type,'christmas');
assert.equal(H('2026-06-15',{preview_date:'2026-13-40'}).type,'none');
assert.equal(H('2026-06-15',{preview_holiday:'none'}).type,'none');
const utcBeforeMidnight=new Date('2026-12-15T23:30:00Z');
assert.equal(holidayForDate(utcBeforeMidnight,'Europe/Bratislava').type,'advent');
